# Dean Louder, Rencontres et voyages en Franco-Amérique, Québec, Septentrion (coll. Hamac-carnets), 2013.
# PDF du Drive de l'auteur (HISTOIRE_LIVRES/DEAN_LOUDER), lu en entier le 19 novembre 2026 par la visionneuse du Drive (200 p.).
# 69 billets de blogue (2003-2011). On ne retient que les faits historiques datés absents de l'atlas
# (French Prairie, Champoeg, Gallipolis, Natchitoches, Morin, etc. y sont déjà). Préfixe LO13.
from commun import Corpus
S = "Louder, Dean (2013), Rencontres et voyages en Franco-Amérique, Québec, Septentrion (Hamac-carnets)"
C = Corpus('Recherches', 'LO13', S, page_fmt='p. {} (PDF)')
F = C.F
F('01', "Saint-Joseph-sur-Lac-Huron (Ontario) : bûcherons du Bas-Canada, la paroisse Saint-Pierre-du-Lac-Huron et la « cité » rêvée de Narcisse Cantin", 'etablissement', '1830/1920', -81.720, 43.400, 'c', ['Claude Gélinas', 'Abraham Bédard', 'Baptiste Durand', 'Narcisse Cantin', 'frère André'],
  "Dans les années 1830, des bûcherons du Bas-Canada (Claude Gélinas, Abraham Bédard, Baptiste Durand) viennent travailler sur la rive du lac Huron ; ils reviennent dix ans plus tard avec leurs familles et forment la seule communauté canadienne-française entre la baie Georgienne et la région de Détroit (Laporte, Denomme, Bedour, Cantin, Papineau, Ducharme, Desjardins, Gravel). L'église Saint-Pierre-du-Lac-Huron est bâtie en 1873. Né là en 1870, Narcisse Cantin rêve d'une grande cité de Saint-Joseph, avec port, canal vers Port Stanley sur le lac Érié et chemin de fer, qui rapatrierait les Canadiens français partis aux États-Unis. Le village connaît son apogée vers 1915-1920 (scierie, briqueterie, grand hôtel) ; le frère André y séjourne en octobre 1917. Dès la fin du XIXe siècle pourtant, la plupart des pierres tombales sont gravées en anglais.",
  '12-14', "Louder tient ces renseignements de l'historien Yves Frenette.")
F('02', "Cardinal (Manitoba) : la chapelle de la Société de Saint-Louis, bâtie de 1927 à 1929 par des colons français et suisses", 'religion', '1927/1950', -98.480, 49.470, 'a', ['Cyprien Cardinal', 'Jean-Baptiste Château', 'Jean Schumacher', 'Théophile Toutant', 'Lucien Vigier'],
  "Arrivés l'année précédente et regroupés en Société de Saint-Louis, Cyprien Cardinal, Jean-Baptiste Château, Jean Schumacher, Théophile Toutant et Lucien Vigier élèvent de 1927 à 1929 une chapelle blanche près de Notre-Dame-de-Lourdes. Elle ne reçoit ni prêtre ni bénédiction avant 1935, quand l'archevêque Yelle permet au père Champagne d'y dire la messe l'hiver. On n'y célèbre ensuite que deux baptêmes (Élise Fouasse, 1945 ; Robert Pittet, 1949) et un mariage (André Talbot et Thérèse Cérénini, 1950). La chapelle est aujourd'hui abandonnée.",
  '20-21', "Point approximatif du hameau de Cardinal, entre Saint-Léon et Notre-Dame-de-Lourdes.")
F('03', "Notre-Dame-de-Lourdes (Manitoba) : les colons de l'est de la France et de Suisse amenés par le chanoine Dom Benoît (1891)", 'etablissement', '1891/1895', -98.550, 49.530, 'c', ['Dom Benoît'],
  "En 1891, des familles de l'est de la France et de Suisse, auxquelles le chanoine Dom Benoît avait donné rendez-vous au port d'Anvers, fondent Notre-Dame-de-Lourdes ; quatre ans plus tard, à la demande du chanoine, des chanoinesses arrivent de Lyon. Des Bretons et d'autres suivent. Louder relève les patronymes Delaquis, Dupasquier, Jamault, Deleurme et Pantel ; le Centre Dom-Benoît regroupe aujourd'hui les services du village.",
  '20-22', "")
F('04', "Saint-Isidore (Alberta) : dernière colonisation de l'Ouest canadien par l'Église, des familles du Lac-Saint-Jean (1953)", 'migration', '1953', -117.100, 56.200, 'c', [],
  "En 1953, les Bergeron, Lavoie, Bouchard, Gagnon et Martel quittent le Lac-Saint-Jean pour défricher un établissement près de Peace River, dans le nord de l'Alberta, à proximité de villages canadiens-français fondés quarante ans plus tôt (Falher, Donnelly, Girouxville, Marie-Reine, Tangent). C'est, selon Louder, la dernière tentative de colonisation de l'Ouest canadien par l'Église catholique.",
  '23-24', "Témoignage de l'historienne Anne Gagnon, née à Saint-Isidore.")
F('05', "Fond du Lac et Oconto (Wisconsin) : Adolphe Papineau, fils d'un réfugié des troubles de 1837 (1857-1861)", 'famille', '1857/1861', -88.447, 43.773, 'h', ['Adolphe Papineau', 'Henriette Landry'],
  "Un parent de Louis-Joseph Papineau, qui a dû fuir le Bas-Canada lors des troubles de 1837, emmène en Nouvelle-Angleterre son fils Adolphe (né en 1834). Adolphe et sa femme Henriette Landry ont un premier enfant à Fond du Lac en 1857, Georges en 1859 et un troisième deux ans plus tard ; ils finissent leurs jours à Oconto, près de la frontière du Michigan. Leur descendant Mike Papineau, né à Chicago d'une famille installée au Nebraska grâce au Homestead Act, cherche encore l'identité de l'ancêtre.",
  '41-42', "Généalogie familiale rapportée par Louder ; filiation non établie par des actes.")
F('06', "Delisle (Mississippi) : les familles « French » et créoles de la baie Saint-Louis, établies dès 1712", 'etablissement', '1712/2004', -89.255, 30.380, 'c', [],
  "Delisle, sur la baie Saint-Louis, est établi en 1712 par des Canadiens. Les familles qui se disent « French » descendent de Français et de Canadiens du début du XVIIIe siècle, parfois de l'équipage des frères Le Moyne ; les familles créoles y ajoutent des réfugiés de Saint-Domingue et des Autochtones de la côte. Les noms les plus répandus (Dedeaux, Swanier, Saucier, Ladner, Nicase, Jurette) sont partagés par les deux groupes. En 2004, les derniers locuteurs du français ou du créole ont plus de 80 ans ; la paroisse compte trois églises séparées : St. William, St. Ann-Dubuisson (vieilles familles blanches) et St. Stephen (créole).",
  '50-54, 134', "Date de 1712 donnée par Louder (p. 134).")
F('07', "Pass Christian (Mississippi) : le nom de Christian L'Adnier, de l'équipage d'Iberville", 'toponymie', '1699/1720', -89.247, 30.316, 'c', ["Christian L'Adnier", "Pierre Le Moyne d'Iberville"],
  "La ville de Pass Christian porte le nom de Christian L'Adnier, membre de l'équipage de d'Iberville. Les L'Adnier, devenus Ladner, forment avec les Dedeaux, Swanier et Saucier l'une des familles francophones les plus nombreuses de l'État.",
  '134', "Louder ne date pas le nom ; intervalle fixé d'après l'époque d'Iberville et de Delisle.")
F('08', "Frenchville (Pennsylvanie) : Normands et Picards au pays des quakers (1830-1836) et le curé Berbigier (1846-1886)", 'etablissement', '1830/1920', -78.233, 41.105, 'c', ['John Keating', 'Jean-Baptiste Berbigier'],
  "Un riche Philadelphien endetté envers un marchand parisien lui cède, par l'entremise de son agent John Keating, le territoire de Frenchville. Entre 1830 et 1836, aidés des sulpiciens de Baltimore et de Philadelphie, des Normands et des Picards (Bilotte, Roussey, Beauseigner, Coudriet, Renaud, Plubelle, Rougeux, Valimont, Picard, Guenot) s'y établissent ; bûcherons et draveurs, ils font flotter le bois jusqu'à Lock Haven. Né en France en 1822, le père Jean-Baptiste Berbigier est leur curé de 1846 à 1886, après quoi il n'y a plus de prêtre francophone. Le français reste la langue publique jusqu'aux années 1920. En 2004, Kenny et Nestor Bilotte sont les deux derniers à le parler.",
  '54-57', "Louder note que ce territoire aurait appartenu de 1753 à 1758 à l'archevêché de Québec, affirmation qu'il ne justifie pas.")
F('09', "La Vieille Mine (Missouri) : les cylindres de cire enregistrés par Joseph-Médard Carrière en 1937 et le cimetière Saint-Joachim", 'evenement', '1937/2005', -90.780, 38.010, 'c', ['Joseph-Médard Carrière', 'Kent Beaulne', 'Charlot Pashia'],
  "En 1937, l'ethnologue franco-ontarien Joseph-Médard Carrière enregistre sur cylindres de cire les habitants de la Vieille Mine ; la Société historique du lieu les rapatrie vers 2003, avec un gramophone pour les faire jouer. Derrière l'église Saint-Joachim, les tombes portent des noms que le curé américain transcrivait au son : Degonia (Desgagné), Reando (Riendeau), Osia (Auger), Bourisaw (Bourassa), Courtaway (Courtois), Merseal (Mercille), DeClue (Duclos). En 1978, Louder y avait encore parlé français avec Eilene Coleman Villmere, Rosie Pratt, Pete Boyer et le violoneux Charlot Pashia.",
  '83-86', "")
F('10', "Vincennes : les tombes des Canadiens qui servirent sous le drapeau américain et le recteur martiniquais Jean-François Rivet", 'personnage', '1778/1806', -87.528, 38.680, 'c', ['Pierre Gibault', 'François Busseron', 'Jean-Marie Philippe Le Gras', 'Jean-François Rivet'],
  "Envoyé par George Rogers Clark, l'abbé Pierre Gibault rallie sans peine les Canadiens de Vincennes à la cause américaine. Une dizaine de pierres tombales rappellent ceux qui servirent sous le drapeau américain : Joseph Dubois, Pierre Grimard, Louis Victor Edeline, Michel Brouillette, Jean-Marie Philippe Le Gras, François Busseron, Nicholas Cardinal, Pierre Levry dit Martin, François Pelletier et André Languedoc. Prêtre et éducateur d'origine martiniquaise, le révérend Jean-François Rivet est le premier recteur de l'Académie Jefferson, future Université de Vincennes.",
  '86-87', "Intervalle de dates indicatif (guerre de l'Indépendance, Académie Jefferson) ; Louder ne date pas les tombes.")
F('11', "Lafontaine (Ontario) : voyageurs et Métis de l'île Drummond (1830), puis colons de Batiscan, Joliette et Vaudreuil-Soulanges", 'migration', '1830/1856', -79.970, 44.750, 'c', [],
  "Après une présence française intermittente de 1610 à 1650 (traiteurs, soldats, missionnaires), un groupe de voyageurs canadiens-français et métis venus de l'île Drummond s'installe à Lafontaine, sur la baie Georgienne, en 1830. Suivent des vagues d'immigrants du Québec, venus surtout de Batiscan, de Joliette et des comtés de Soulanges et de Vaudreuil. La paroisse Sainte-Croix est fondée en 1856. Les Marchildon, l'une des familles bâtisseuses, issue de Batiscan, ont aussi été pionniers à Zénon Park, en Saskatchewan.",
  '113-114', "")
F('12', "Lebret, vallée de la Qu'Appelle : la mission fondée par Mgr Taché (1865) et l'école du père Hugonard (1880)", 'religion', '1865/1880', -103.705, 50.755, 'c', ['Alexandre-Antonin Taché', 'abbé Ritchot', 'Jules Decorby', 'Joseph Hugonard', 'Louis Lebret'],
  "Mgr Taché fonde en 1865 la mission de Qu'Appelle, où le père Ritchot élève la première chapelle l'année suivante. Le père Jules Decorby, premier prêtre résident, y reste de 1868 à 1880 ; il est remplacé par le père Joseph Hugonard (1848-1917), originaire de l'Isère, missionnaire des Indiens et des Métis, qui y établit la première école pour Autochtones. Le village porte le nom du premier maître de poste, l'abbé Louis Lebret.",
  '115-117', "")
F('13', "Willow Bunch (Talle de Saules) : Jean-Louis Légaré, négociateur auprès de Sitting Bull, fonde le village (1876-1880)", 'etablissement', '1876/1880', -105.650, 49.380, 'c', ['Jean-Louis Légaré', 'Sitting Bull'],
  "Commerçant, charretier et aventurier né à Saint-Jacques-de-l'Achigan, Jean-Louis Légaré passe par Saint Paul (Minnesota) et Pembina avant de s'établir en Saskatchewan. De 1876 à 1880, il négocie avec les Métis et les Amérindiens de la région, dont Sitting Bull, réfugié là avec sa bande après Little Bighorn, en lien avec la police montée du Nord-Ouest. Il fonde Willow Bunch en 1880.",
  '117-118', "")
F('14', "Bathgate (Dakota du Nord) : la mort de Victor Charigot, beau-père de Renoir (1898)", 'personnage', '1860/1898', -97.477, 48.877, 'c', ['Victor Charigot', 'Jean-Baptiste Genin'],
  "Claude dit Victor Charigot, Champenois, abandonne en 1860 sa femme et sa fille Aline, future épouse du peintre Pierre-Auguste Renoir. Endetté et poursuivi, il passe par le Canada avant d'entrer aux États-Unis, prend une seconde épouse au Manitoba et une troisième au Dakota du Nord, et meurt à Bathgate en 1898. Commerçant au village, il y côtoie sans doute le père Jean-Baptiste Genin (1839-1900), missionnaire des Métis et des Canadiens, qui a pu présider ses obsèques.",
  '119-121', "Louder s'appuie sur l'essai de Pierre Chartrand et Bernard Pharisien (2004) ; les obsèques par Genin sont une hypothèse.")
F('15', "Frenchtown (Petit Saint-Louis, Indiana) : la paroisse française des années 1840 et les Paté du Doubs (1855)", 'etablissement', '1840/1885', -86.205, 38.330, 'c', ['Jean-Pierre Dion', 'Martin Paté'],
  "Frenchtown, autrefois Petit Saint-Louis, à une quarantaine de kilomètres à l'ouest de New Albany, est peuplé au début des années 1840 par des Français et quelques Canadiens ; jusqu'aux années 1880, sous le pasteur Jean-Pierre Dion puis peut-être le père Martin Andrès, la paroisse vit en français. Martin Paté et sa famille, du Doubs, débarquent à La Nouvelle-Orléans le 1er mai 1855 à bord de l'International, avec Virgil Deschamps et Hypolite Colin ; établis d'abord dans le canton de Washington, ils gagnent Frenchtown avec d'autres Alsaciens et Lorrains (Troncin, Boncourt, Semonin, Brocard, Thirrion, Lasson). La paroisse Saint-Bernard est aujourd'hui anglophone.",
  '148-149', "D'après la brochure French Immigrants to Clark, Floyd and Harrison Counties in Indiana (bibliothèque de New Albany).")
F('16', "Beaumont (Alberta) : les familles de l'abbé Morin (1892) et l'église Saint-Vital (1894-1895)", 'religion', '1892/1895-06-30', -113.415, 53.355, 'c', ['Jean-Baptiste Morin', 'Albert Lacombe', 'Vital Grandin'],
  "Attirées par l'abbé Jean-Baptiste Morin, agent de colonisation, les premières familles canadiennes-françaises arrivent à Beaumont en 1892. En 1894, à la demande de Mgr Vital Grandin, le père Lacombe achète dix acres pour 50 $ afin d'y bâtir une église ; la paroisse est nommée Saint-Vital en l'honneur de l'évêque et la première messe y est célébrée le 30 juin 1895. Beaumont est aujourd'hui l'une des trois municipalités officiellement bilingues de l'Alberta, avec Legal et Bonnyville.",
  '150-152', "")
F('17', "Morinville : les Filles de Jésus de Kermaria, chassées de Bretagne, s'installent près de l'église (1902)", 'religion', '1902', -113.640, 53.800, 'c', ['Jean-Baptiste Morin'],
  "Entre 1891 et 1899, l'abbé Jean-Baptiste Morin aide 600 familles canadiennes-françaises à s'établir dans l'Ouest, la plupart à Morinville. En 1902, des Filles de Jésus de Kermaria, en Bretagne, quittent la France sous la menace d'expulsion et s'installent dans un couvent voisin de l'église, aujourd'hui musée sur la place Jean-Baptiste. Une fresque représente l'arrivée des premiers colons, québécois et allemands.",
  '161-165', "Complète FA-ka04 (Morin).")
F('18', "Frenchtown (Walla Walla) : la maison de Joseph LaRoque (1823), les Letellier et les cabanes métisses antérieures à Whitman", 'etablissement', '1823/1855', -118.450, 46.050, 'c', ['Joseph LaRoque', 'Louis Letellier', 'Jean-Baptiste Brouillet', 'Eugène Chirouse', 'Suzanne Cayouse Dauphin', 'Sam Pambrun'],
  "Selon l'historien métis Sam Pambrun (réserve d'Umatilla), Joseph LaRoque bâtit la première maison de Frenchtown (aujourd'hui Lowden, à 12 km à l'ouest de Walla Walla) en 1823 ; la famille de Louis Letellier arrive du Montana dix ans plus tard. D'autres voyageurs canadiens et métis, venus en partie de la rivière Rouge, s'y retirent de la traite. En 1836, quand Marcus Whitman fonde sa mission, il y a déjà une douzaine de maisons en rondins métisses, que Whitman ne mentionne jamais. La fondation historique de Frenchtown veut mettre en valeur le site de la bataille de Walla Walla (1855) et la mission Sainte-Rose des pères Brouillet et Chirouse ; Suzanne Cayouse Dauphin est l'une des ancêtres honorées au Rendez-vous de 2010.",
  '165-168', "Le texte imprime « Chioreuse » pour Chirouse.")
F('19', "Belmont Park (New York) : Lucien Laurin et Ron Turcotte mènent Secretariat à la Triple Couronne (1973)", 'personnage', '1973', -73.720, 40.715, 'c', ['Lucien Laurin', 'Ron Turcotte'],
  "Né en 1912 près de Joliette, Lucien Laurin monte pour la première fois à Blue Bonnets (Montréal) en 1929, remporte 161 courses et devient entraîneur en 1942. Il fait engager comme jockey Ron Turcotte, né en 1941 à Drummond (Nouveau-Brunswick), parti en 1960 travailler à Woodbine (Toronto). Ensemble, ils mènent Secretariat à la Triple Couronne en 1973 ; au Belmont, le cheval gagne par 31 longueurs. Turcotte est paralysé par une chute à Belmont le 13 juillet 1978 ; le pont de Grand-Sault porte son nom.",
  '169-172', "")
F('20', "White Bear Lake (Minnesota) : le charpentier mauricien Élie Lemire épouse Philamine LaBore près de Little Canada (1884)", 'famille', '1884', -93.010, 45.085, 'c', ['Élie Lemire', 'Marie Josephine Philamine LaBore'],
  "Né en Mauricie en 1861, le charpentier Élie Lemire tente sa chance aux États-Unis vers 1880 et épouse en 1884, à White Bear Lake, près du village de Little Canada, Marie Josephine Philamine LaBore. Ils ont neuf enfants avant sa mort en 1922. Le français se parle encore entre son fils Joseph Charles (né en 1896) et ses amis canadiens de White Bear Lake et de Little Canada, mais plus à la maison.",
  '184-185', "")
F('21', "Caribou (Maine) : Jean-Pierre Lévesque, de Kamouraska, devenu Leveck (années 1850)", 'famille', '1850/1919', -68.013, 46.861, 'c', ['Jean-Pierre Lévesque', 'Susan Little', 'Sandy Leveck'],
  "Né à Kamouraska vers 1805, Jean-Pierre Lévesque quitte son village pour le Nouveau-Brunswick vers 1850, épouse Susan Little en 1854 et s'établit à Caribou, dans le Maine. Leurs enfants sont élevés dans la foi méthodiste ; le nom devient Leveck. Le petit-fils Sandy (né en 1900), soldat posté à McAllen (Texas) en 1919, y épouse la Mexicaine-Américaine Elodia McDonald.",
  '192-193', "")
fiches = C.fiches
